import {booking} from "../common/request.mjs";
import {renew} from "../common/renewals.mjs";

function reserveStudio(ledger, request, catalog) {
  // Share the journal and admission semantics, but not the platform's capacity
  // policy. This synchronous view leaves the original ledger/catalog untouched.
  const admission = Object.create(ledger);
  admission.catalog = {
    ...catalog,
    default: catalog.studios.get(request.tenant) ?? catalog.default
  };
  return ledger.reserve.call(admission, request);
}

export function bookStudio(ledger, input, catalog) {
  return reserveStudio(ledger, booking(input), catalog);
}

export function renewStudio(ledger, operation, catalog) {
  // Keep the shared renewal validation and tenant inheritance, routing its
  // admission through the same Studio policy as direct bookings.
  const renewal = Object.create(ledger);
  renewal.reserve = request => reserveStudio(ledger, request, catalog);
  return renew(renewal, operation);
}
