test("Studio quotas retain replay, conflicts, cancellation and renewal semantics", () => {
  const dispatch = planner(readCatalog());
  const first = booking("first", 7);
  assert.deepEqual(dispatch(first), {status:"booked", id:"first", remaining:1});
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch({...first, units:6}).status, "conflict");
  assert.deepEqual(dispatch(booking("too-much", 2)), {status:"full", id:"too-much", remaining:1});
  assert.deepEqual(dispatch(booking("last", 1)), {status:"booked", id:"last", remaining:0});
  assert.equal(dispatch(first).status, "replay");
  assert.equal(dispatch(renewal("first", "next")).status, "booked");
  assert.equal(dispatch(renewal("first", "next")).status, "replay");
  assert.equal(dispatch(renewal("first", "next", {units:6})).status, "conflict");
  assert.equal(dispatch(renewal("first", "overflow", {units:2})).status, "full");
  assert.equal(dispatch({service:"studio", action:"cancel", id:"first"}).status, "cancelled");
  assert.equal(dispatch(first).status, "cancelled");
  assert.equal(dispatch(renewal("first", "inactive")).status, "missing");
  assert.equal(dispatch(renewal("absent", "missing")).status, "missing");
  assert.deepEqual(dispatch(booking("replacement", 7)), {status:"booked", id:"replacement", remaining:0});
  assert.deepEqual(dispatch({service:"studio", action:"usage", tenant:"orchid", day:"2025-04-02"}), {units:8});
  assert.equal(dispatch({service:"studio", action:"summary"}).events.length, 5);
  assert.equal(apply(dispatch, booking("invalid", 0)).status, "invalid");
});

